    "unit": 3,
    "topicId": "3.2.2",
    "relatedTopicIds": [],
    "term": "Primary Research",
    "termZh": "一手调研",
    "definitionEn": "Collecting original, first-hand data directly related to the business’s needs.",
    "explanationZh": "企业为当前问题直接收集的原始数据，例如访谈、问卷或观察结果。",
    "exampleEn": "The product team conducted primary research by asking recent buyers why they had returned the new blender.",
