    "termZh": "每股股息",
    "definitionEn": "The total dividend declared for ordinary shareholders divided by the number of ordinary shares entitled to it.",
    "explanationZh": "普通股股东可获派息总额除以有权收取股息的普通股股数。",
    "exampleEn": "The company raised its dividend per share by 4%, although the board warned that future increases would depend on cash generation.",
    "exampleZh": "公司把每股股息提高了 4%，不过董事会提醒，未来能否继续提高取决于现金创造能力。"
