    "explanationZh": "股价除以每股收益所得的比率，反映投资者愿意为每单位当前盈利支付多少价格；高市盈率也可能意味着更高预期或估值风险。",
    "exampleEn": "The price/earnings ratio was higher than that of rivals, so the analyst asked whether the forecast growth justified the premium.",
    "exampleZh": "这家公司的市盈率高于竞争对手，因此分析师询问预期增长是否足以支撑估值溢价。"
